/* SERVICES */
static struct lpass_cdc_priv p;static atomic_int entered,done;static bool comp;
static void *drain(void*x){atomic_store(&entered,1);if(comp)lpass_cdc_component_drain(&p);else lpass_cdc_quiesce(&p);atomic_store(&done,1);return NULL;}
int main(void){struct device d={0};init_priv(&p,&d);assert(!lpass_cdc_op_get(NULL,false));assert(!lpass_cdc_op_get(&p,true));p.component_ready=true;assert(lpass_cdc_op_get(&p,false));assert(lpass_cdc_op_get(&p,false));lpass_cdc_op_put(&p,false);pthread_t t;pthread_create(&t,NULL,drain,NULL);while(!atomic_load(&entered))usleep(100);usleep(20000);assert(!atomic_load(&done));assert(!lpass_cdc_op_get(&p,false));lpass_cdc_op_put(&p,false);pthread_join(t,NULL);assert(atomic_load(&done));lpass_cdc_reopen(&p);comp=true;atomic_store(&entered,0);atomic_store(&done,0);assert(lpass_cdc_op_get(&p,true));pthread_create(&t,NULL,drain,NULL);while(!atomic_load(&entered))usleep(100);usleep(20000);assert(!atomic_load(&done));assert(!lpass_cdc_op_get(&p,true));assert(lpass_cdc_op_get(&p,false));lpass_cdc_op_put(&p,false);lpass_cdc_op_put(&p,true);pthread_join(t,NULL);assert(atomic_load(&done)&&!atomic_read(&p.active_ops));printf("{\"gate\":10}\n");}
